    trigger = (label2) => ({ type: "trigger", ...named(label2), config: { modes: ["manual"] } });
    output2 = (label2, value) => ({ type: "output", ...named(label2), config: { value } });
    rule = (label2, condition2) => ({ type: "rule", ...named(label2), config: { mode: "ifElse", condition: condition2 } });
    cases = (label2, value, ports) => ({
      type: "rule",
      ...named(label2),
      config: { mode: "switch", value, cases: ports.map((port) => ({ value: port, port })) }
    });
    llm = (model, label2, prompt, maxTokens = 800) => ({
      type: "llm",
      ...named(label2),
      config: {
        provider: model.provider,
        model: model.model,
        connection: CONNECTION,
        prompt,
        responseFormat: "text",
        generation: { maxTokens, stream: true },
        execution: EXECUTION,
        historyScope: "none"
      }
    });
    decision = (model, label2, state, questions) => ({
      type: "decision",
      ...named(label2),
      config: {
        provider: "llm",
        model: model.model,
        llm: { provider: model.provider, generation: { maxTokens: 400, stream: true } },
        connection: CONNECTION,
        state,
        execution: EXECUTION,
        questions
      }
    });
    approval = (label2, question3, input2, inputSchema) => ({
      type: "humanApproval",
      ...named(label2),
      config: { title: question3, input: input2, inputSchema, actions: ["approve", "reject"], expiresAfter: "24h", onReject: "cancelled", onTimeout: "expired" }
    });
    pick2 = (language, en, zh) => language === "zh" ? zh : en;
